        avg_order_value as avg_order_value,
        high_value_orders as high_value_orders,
        customer_type as customer_type,
        recency_days as recency_days,
        r_score as r_score,
        f_score as f_score,
        m_score as m_score,
        rfm_score as rfm_score,
        (case when (count_lifetime_orders = 0) then 'PROSPECT' else case when (rfm_score = 333) then 'CHAMPION' else case when (((r_score = 3) and (f_score >= 2)) and (m_score >= 2)) then 'LOYAL' else case when ((r_score = 1) and (f_score >= 2)) then 'AT_RISK' else 'STANDARD' end end end end) as rfm_segment
    from exp_rfm_scores
),

final as (
    -- CUSTOMER_360 (Target CUSTOMER_360): cast to the target column types
    select
        cast(customer_id as varchar) as customer_id,
        cast(customer_name as varchar) as customer_name,
        cast(count_lifetime_orders as decimal(15, 0)) as count_lifetime_orders,
        cast(first_ordered_at as timestamp) as first_ordered_at,
        cast(last_ordered_at as timestamp) as last_ordered_at,
        cast(lifetime_spend as decimal(12, 2)) as lifetime_spend_pretax,
        cast(lifetime_spend_pretax as decimal(12, 2)) as lifetime_tax_paid,
