        cast(high_value_orders as decimal(15, 0)) as high_value_orders,
        cast(customer_type as varchar) as customer_type,
        cast(recency_days as decimal(15, 0)) as recency_days,
        cast(r_score as decimal(1, 0)) as r_score,
        cast(f_score as decimal(1, 0)) as f_score,
        cast(m_score as decimal(1, 0)) as m_score,
        cast(rfm_score as decimal(15, 0)) as rfm_score,
        cast(rfm_segment as varchar) as rfm_segment
